def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = []
    for start, end in sorted_intervals:
        if not merged:
            merged.append((start, end))
        elif start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))

    return merged
