import heapq

def topo_sort(graph):
    nodes = set(graph.keys())
    for node, prereqs in graph.items():
        nodes.update(prereqs)

    in_degree = {}
    for prereqs in graph.values():
        for p in prereqs:
            in_degree[p] = in_degree.get(p, 0) + 1

    ready = [n for n in nodes if in_degree.get(n, 0) == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        node = heapq.heappop(ready)
        result.append(node)
        for p in graph.get(node, []):
            in_degree[p] -= 1
            if in_degree[p] == 0:
                heapq.heappush(ready, p)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
